class Solution:
    def finalPositionOfSnake(self, n: int, commands: List[str]) -> int:
        # Start at position 0, which is (0, 0)
        row, col = 0, 0

        # Process each command
        for command in commands:
            if command == "RIGHT":
                col += 1
            elif command == "LEFT":
                col -= 1
            elif command == "DOWN":
                row += 1
            elif command == "UP":
                row -= 1

        # Convert final (row, col) position to grid value
        return row * n + col

class Solution:
    def winningPlayerCount(self, n: int, pick: List[List[int]]) -> int:
        # Dictionary to store count of each color for each player
        player_color_count = {}

        # Initialize for each player
        for i in range(n):
            player_color_count[i] = {}

        # Process each pick
        for player, color in pick:
            if color not in player_color_count[player]:
                player_color_count[player][color] = 0
            player_color_count[player][color] += 1

        # Count winning players
        winning_count = 0

        for player in range(n):
            # Player i wins if they have at least (i+1) balls of the same color
            max_count_for_color = 0
            for color, count in player_color_count[player].items():
                max_count_for_color = max(max_count_for_color, count)

            # Check if player wins
            if max_count_for_color >= player + 1:
                winning_count += 1

        return winning_count

class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        # Calculate flips needed for all rows to be palindromic
        row_flips = 0
        for i in range(m):
            for j in range(n // 2):
                if grid[i][j] != grid[i][n - 1 - j]:
                    row_flips += 1

        # Calculate flips needed for all columns to be palindromic
        col_flips = 0
        for j in range(n):
            for i in range(m // 2):
                if grid[i][j] != grid[m - 1 - i][j]:
                    col_flips += 1

        # Return minimum flips needed
        return min(row_flips, col_flips)

